<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{Product,Release}; use App\Services\{AuditService,PackageService}; use Illuminate\Http\Request; use Illuminate\Support\Facades\{DB,Storage}; use Illuminate\Support\Str;
class ReleaseController extends Controller { public function index(){return view('admin.resource',['title'=>__('ui.releases'),'columns'=>['version','channel','status','package_sha256'],'rows'=>Release::with('product')->latest()->paginate(20),'createRoute'=>route('releases.create'),'actions'=>'releases']);} public function create(){return view('admin.release-form',['products'=>Product::where('status','active')->get()]);} public function store(Request $r,AuditService $audit,PackageService $packages){$data=$r->validate(['product_id'=>'required|exists:products,id','version'=>['required','regex:/^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-[0-9A-Za-z.-]+)?$/'],'channel'=>'required|in:stable,beta,alpha,internal','release_notes'=>'nullable|string','package'=>'required|file|mimes:zip|max:1048576']);$file=$r->file('package');$inspection=$packages->inspect($file);return DB::transaction(function()use($data,$file,$inspection,$audit){$uuid=(string)Str::uuid();$name=preg_replace('/[^A-Za-z0-9._-]/','_',basename($file->getClientOriginalName()));$path="packages/{$data['product_id']}/{$uuid}/{$name}";Storage::disk(config('office.package_disk'))->putFileAs(dirname($path),$file,basename($path));$release=Release::create(['uuid'=>$uuid,'product_id'=>$data['product_id'],'version'=>$data['version'],'channel'=>$data['channel'],'status'=>'draft','source_type'=>'manual','release_notes'=>$data['release_notes']??null,'package_filename'=>$name,'package_path'=>$path,'package_size'=>$inspection['size'],'package_sha256'=>$inspection['sha256']]);$audit->record('release.created',$release,null,$release->toArray());return redirect()->route('releases.index')->with('success',__('ui.saved'));});} public function publish(Release $release,AuditService $audit){abort_if($release->status->value!=='draft'||!$release->package_path,409);DB::transaction(function()use($release,$audit){$before=$release->toArray();$release->update(['status'=>'published','published_at'=>now()]);$audit->record('release.published',$release,$before,$release->fresh()->toArray());});return back()->with('success',__('ui.published'));} }
